import APIService from '../../../../Services/APIService';
import { Apis } from '../../../../Services/app.constants';

export const recordStatusLogService = {
  async fetchStatusLogs(leadId) {
    if (!leadId) throw new Error('Lead ID is required');
    return APIService.get(`${Apis.updateLeadStatus1}?id=${encodeURIComponent(leadId)}`);
  },
};
